#[cfg(all(archstaler_package = "imobiledevice", archstaler_target = "plist"))]
pub use __archstaler_source::*;

#[cfg(all(archstaler_package = "net", archstaler_target = "net"))]
pub mod __archstaler_source {
//! Networking on top of smoltcp: DHCP, DNS, TCP and a small HTTP/1.1 client.
extern crate alloc;

pub mod client {
//! `http://` and `https://` GET with redirect following.
use crate::__archstaler_source::http::{self, Response};
use crate::__archstaler_source::tls::{self, TlsStream};
use crate::__archstaler_source::{Error, Result, Stack, Stream};
use alloc::string::String;
use alloc::sync::Arc;
use rustls::ClientConfig;

const MAX_REDIRECTS: usize = 5;

pub struct Client {
    tls: Arc<ClientConfig>,
}

struct Url<'a> {
    https: bool,
    host: &'a str,
    port: u16,
    path: &'a str,
}

fn parse(url: &str) -> Result<Url<'_>> {
    let (https, rest) = if let Some(r) = url.strip_prefix("https://") {
        (true, r)
    } else if let Some(r) = url.strip_prefix("http://") {
        (false, r)
    } else {
        return Err(Error::Http("unsupported URL scheme"));
    };
    let (authority, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match authority.rsplit_once(':') {
        Some((h, p)) => (h, p.parse().map_err(|_| Error::Http("bad port"))?),
        None => (authority, if https { 443 } else { 80 }),
    };
    if host.is_empty() {
        return Err(Error::Http("empty host"));
    }
    Ok(Url { https, host, port, path })
}

/// The URL a `Location` header points to, seen from `path` on `host` (which includes a non-default port).
fn redirect_target(https: bool, host: &str, path: &str, loc: String) -> String {
    let scheme = if https { "https" } else { "http" };
    if loc.contains("://") {
        loc
    } else if let Some(rest) = loc.strip_prefix("//") {
        alloc::format!("{scheme}://{rest}")
    } else if loc.starts_with('/') {
        alloc::format!("{scheme}://{host}{loc}")
    } else {
        // Relative to the directory of the current path (RFC 3986 reference resolution, simplified).
        let dir = &path[..path.rfind('/').map_or(0, |i| i + 1)];
        alloc::format!("{scheme}://{host}{dir}{loc}")
    }
}

impl Client {
    pub fn new(unix_time: fn() -> u64) -> Client {
        Client { tls: tls::client_config(unix_time) }
    }

    /// GET `url`, following redirects, delivering the body of the final 2xx response to `sink`.
    /// Returns the final response (status may be an error status, in which case no body was
    /// delivered).
    pub fn get(&self, stack: &mut Stack, url: &str, sink: &mut dyn FnMut(&[u8]) -> Result<()>) -> Result<Response> {
        let mut current = String::from(url);
        for _ in 0..=MAX_REDIRECTS {
            let u = parse(&current)?;
            let now = stack.clock();
            let t0 = now();
            let ip = stack.resolve(u.host, 8000).map_err(|e| {
                hal::info!("net: DNS lookup of {} failed after {} ms: {e:?}", u.host, now() - t0);
                e
            })?;
            hal::log!("net: {} is {}.{}.{}.{} ({} ms)", u.host, ip[0], ip[1], ip[2], ip[3], now() - t0);
            let host_header = if (u.https && u.port == 443) || (!u.https && u.port == 80) { String::from(u.host) } else { alloc::format!("{}:{}", u.host, u.port) };
            let t1 = now();
            let conn = stack.connect(ip, u.port, 8000).map_err(|e| {
                hal::info!("net: TCP connect to {}:{} failed after {} ms: {e:?}", u.host, u.port, now() - t1);
                e
            })?;
            let resp = if u.https {
                let t2 = now();
                let mut t = TlsStream::connect(conn, self.tls.clone(), u.host).map_err(|e| {
                    hal::info!("net: TLS handshake with {} failed: {e:?}", u.host);
                    e
                })?;
                hal::log!("net: TCP connected in {} ms, TLS handshake {} ms", t2 - t1, now() - t2);
                let t3 = now();
                let mut got = 0usize;
                let r = http::get(&mut t, &host_header, u.path, &mut |d| {
                    got += d.len();
                    sink(d)
                });
                match &r {
                    Ok(resp) => hal::log!("net: {} HTTP {}, {} body bytes in {} ms", u.path, resp.status, got, now() - t3),
                    Err(e) => hal::info!("net: {} failed after {} body bytes, {} ms: {e:?}", u.path, got, now() - t3),
                }
                r?
            } else {
                let mut c = conn;
                let r = http::get(&mut c, &host_header, u.path, sink)?;
                let _ = c.read(&mut []);
                r
            };
            if matches!(resp.status, 301 | 302 | 303 | 307 | 308) {
                let loc = resp.location.ok_or(Error::Http("redirect without Location"))?;
                current = redirect_target(u.https, &host_header, u.path, loc);
                continue;
            }
            return Ok(resp);
        }
        Err(Error::Http("too many redirects"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn redirect_targets() {
        let t = |https, loc: &str| redirect_target(https, "mirror.example:8443", "/core/os/x86_64/core.db", loc.into());
        assert_eq!(t(true, "http://other.example/x"), "http://other.example/x");
        assert_eq!(t(true, "//cdn.example/core.db"), "https://cdn.example/core.db");
        assert_eq!(t(false, "/archlinux/core.db"), "http://mirror.example:8443/archlinux/core.db");
        assert_eq!(t(true, "core.db.tar.gz"), "https://mirror.example:8443/core/os/x86_64/core.db.tar.gz");
    }
}

}
pub mod http {
//! Minimal HTTP/1.1 GET client with streaming body delivery.
use crate::__archstaler_source::{Error, Result, Stream};
use alloc::string::String;
use alloc::vec::Vec;

pub struct Response {
    pub status: u16,
    pub content_length: Option<u64>,
    pub location: Option<String>,
}

/// Sends `GET path` and streams the body to `sink`. Returns the status line info; the body is
/// only delivered for 2xx responses.
pub fn get<S: Stream>(
    s: &mut S,
    host: &str,
    path: &str,
    sink: &mut dyn FnMut(&[u8]) -> Result<()>,
) -> Result<Response> {
    let mut req = String::new();
    req.push_str("GET ");
    req.push_str(path);
    req.push_str(" HTTP/1.1\r\nHost: ");
    req.push_str(host);
    req.push_str("\r\nUser-Agent: archstaller\r\nAccept: */*\r\nConnection: close\r\n\r\n");
    s.write_all(req.as_bytes())?;

    let mut buf: Vec<u8> = Vec::new();
    let mut tmp = [0u8; 4096];
    let head_end = loop {
        if let Some(p) = find(&buf, b"\r\n\r\n") {
            break p;
        }
        if buf.len() > 16 * 1024 {
            return Err(Error::Http("header too large"));
        }
        let n = s.read(&mut tmp)?;
        if n == 0 {
            return Err(Error::Closed);
        }
        buf.extend_from_slice(&tmp[..n]);
    };
    // Only ASCII headers are read; a stray non-UTF-8 byte in another one (a Latin-1 file name) must not fail the download.
    let head = String::from_utf8_lossy(&buf[..head_end]).into_owned();
    let mut lines = head.split("\r\n");
    let status_line = lines.next().ok_or(Error::Http("no status line"))?;
    let status: u16 = status_line
        .split(' ')
        .nth(1)
        .and_then(|c| c.parse().ok())
        .ok_or(Error::Http("bad status line"))?;
    let mut resp = Response { status, content_length: None, location: None };
    let mut chunked = false;
    for l in lines {
        let Some((k, v)) = l.split_once(':') else { continue };
        let v = v.trim();
        if k.eq_ignore_ascii_case("content-length") {
            resp.content_length = v.parse().ok();
        } else if k.eq_ignore_ascii_case("transfer-encoding") && v.eq_ignore_ascii_case("chunked") {
            chunked = true;
        } else if k.eq_ignore_ascii_case("location") {
            resp.location = Some(v.into());
        }
    }
    let body_start = head_end + 4;
    let leftover: Vec<u8> = buf[body_start..].to_vec();
    drop(buf);
    if !(200..300).contains(&status) {
        return Ok(resp);
    }

    if chunked {
        read_chunked(s, leftover, sink)?;
    } else {
        let mut remaining = resp.content_length;
        let mut deliver = |data: &[u8], remaining: &mut Option<u64>| -> Result<()> {
            let data = match remaining {
                Some(r) => &data[..data.len().min(*r as usize)],
                None => data,
            };
            if let Some(r) = remaining {
                *r -= data.len() as u64;
            }
            if data.is_empty() {
                return Ok(());
            }
            sink(data)
        };
        deliver(&leftover, &mut remaining)?;
        while remaining != Some(0) {
            let n = s.read(&mut tmp)?;
            if n == 0 {
                if remaining.is_some() {
                    return Err(Error::Closed);
                }
                break;
            }
            deliver(&tmp[..n], &mut remaining)?;
        }
    }
    Ok(resp)
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

fn read_chunked<S: Stream>(
    s: &mut S,
    mut pending: Vec<u8>,
    sink: &mut dyn FnMut(&[u8]) -> Result<()>,
) -> Result<()> {
    let mut tmp = [0u8; 4096];
    let mut fill = |pending: &mut Vec<u8>, s: &mut S| -> Result<()> {
        let n = s.read(&mut tmp)?;
        if n == 0 {
            return Err(Error::Closed);
        }
        pending.extend_from_slice(&tmp[..n]);
        Ok(())
    };
    loop {
        // Chunk size line.
        let line_end = loop {
            if let Some(p) = find(&pending, b"\r\n") {
                break p;
            }
            fill(&mut pending, s)?;
        };
        let size_str = core::str::from_utf8(&pending[..line_end]).map_err(|_| Error::Http("bad chunk"))?;
        let size_str = size_str.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16).map_err(|_| Error::Http("bad chunk size"))?;
        pending.drain(..line_end + 2);
        if size == 0 {
            return Ok(());
        }
        let mut left = size;
        while left > 0 {
            if pending.is_empty() {
                fill(&mut pending, s)?;
            }
            let n = pending.len().min(left);
            sink(&pending[..n])?;
            pending.drain(..n);
            left -= n;
        }
        while pending.len() < 2 {
            fill(&mut pending, s)?;
        }
        pending.drain(..2); // CRLF after chunk data
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    extern crate std;

    /// A canned response, read back `step` bytes at a time.
    struct Canned {
        data: Vec<u8>,
        pos: usize,
        step: usize,
        sent: Vec<u8>,
    }

    impl Stream for Canned {
        fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
            let n = self.step.min(buf.len()).min(self.data.len() - self.pos);
            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
            self.pos += n;
            Ok(n)
        }
        fn write_all(&mut self, buf: &[u8]) -> Result<()> {
            self.sent.extend_from_slice(buf);
            Ok(())
        }
    }

    fn fetch(response: &[u8], step: usize) -> (Result<Response>, Vec<u8>) {
        let mut s = Canned { data: response.to_vec(), pos: 0, step, sent: Vec::new() };
        let mut body = Vec::new();
        let r = get(&mut s, "mirror.example", "/core.db", &mut |d| {
            body.extend_from_slice(d);
            Ok(())
        });
        (r, body)
    }

    #[test]
    fn content_length_body() {
        for step in [1, 3, 4096] {
            let (r, body) = fetch(b"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello and more", step);
            assert_eq!(r.unwrap().content_length, Some(5));
            assert_eq!(body, b"hello", "step {step}");
        }
    }

    #[test]
    fn chunked_body_with_extensions_and_trailer() {
        let resp = b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n4;ext=1\r\nWiki\r\n6\r\npedia \r\nE\r\nin \r\n\r\nchunks.\r\n0\r\nX-Trailer: y\r\n\r\n";
        for step in [1, 7, 4096] {
            let (r, body) = fetch(resp, step);
            assert_eq!(r.unwrap().status, 200);
            assert_eq!(body, b"Wikipedia in \r\n\r\nchunks.", "step {step}");
        }
    }

    #[test]
    fn a_non_utf8_header_does_not_fail_the_download() {
        let mut resp = b"HTTP/1.1 200 OK\r\nContent-Disposition: attachment; filename=\"".to_vec();
        resp.extend_from_slice(&[0xe9, b'.', b'd', b'b']); // Latin-1
        resp.extend_from_slice(b"\"\r\nContent-Length: 2\r\n\r\nok");
        let (r, body) = fetch(&resp, 4096);
        assert_eq!(r.unwrap().status, 200);
        assert_eq!(body, b"ok");
    }

    #[test]
    fn redirects_and_errors_deliver_no_body() {
        let (r, body) = fetch(b"HTTP/1.1 302 Found\r\nLocation: https://other.example/core.db\r\nContent-Length: 3\r\n\r\nabc", 4096);
        let r = r.unwrap();
        assert_eq!((r.status, r.location.as_deref()), (302, Some("https://other.example/core.db")));
        assert!(body.is_empty());
        let (r, body) = fetch(b"HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\n\r\nnot found", 4096);
        assert_eq!(r.unwrap().status, 404);
        assert!(body.is_empty());
    }

    #[test]
    fn a_truncated_body_is_an_error() {
        let (r, _) = fetch(b"HTTP/1.1 200 OK\r\nContent-Length: 10\r\n\r\nshort", 4096);
        assert_eq!(r.err(), Some(Error::Closed));
    }
}

}
pub mod stack {
use crate::__archstaler_source::{Error, Result, Stream};
use alloc::boxed::Box;
use alloc::vec;
use alloc::vec::Vec;
use hal::NetDevice;
use smoltcp::iface::{Config, Interface, SocketHandle, SocketSet};
use smoltcp::phy::{self, Device, DeviceCapabilities, Medium};
use smoltcp::socket::{dhcpv4, dns, tcp};
use smoltcp::time::Instant;
use smoltcp::wire::{DnsQueryType, EthernetAddress, HardwareAddress, IpAddress, IpCidr, IpEndpoint, Ipv4Address};

const MTU: usize = 1514;
/// How long a leased address is ARP-probed for conflicts, and how many conflicting offers are declined.
const PROBE_MS: u64 = 1500;
const MAX_DECLINES: u32 = 4;
/// Resolvers tried after the ones DHCP provides (Cloudflare, Google).
const FALLBACK_DNS: [[u8; 4]; 2] = [[1, 1, 1, 1], [8, 8, 8, 8]];
/// TCP receive window. Large enough for a long, fast path (window scaling is on), small enough that a
/// full window fits the NIC receive rings (the largest is 512 KiB), so a burst is not dropped while
/// the CPU is busy decrypting.
const TCP_RX: usize = 256 * 1024;
const TCP_TX: usize = 16 * 1024;

/// Frame counters by kind, to tell "nothing received" from "received but not answered".
#[derive(Default, Clone, Copy)]
struct Counts {
    arp: u32,
    udp: u32,
    tcp: u32,
    other: u32,
    /// Frames addressed to us alone (not broadcast or multicast).
    unicast: u32,
    /// Ethertypes of the frames counted as "other" (type, count), first few kinds only.
    types: [(u16, u32); 6],
    arp_logged: u32,
}

impl Counts {
    fn note(&mut self, dir: &str, f: &[u8]) {
        if f.len() < 14 {
            return;
        }
        if f[0] & 1 == 0 {
            self.unicast += 1;
        }
        let ethertype = u16::from_be_bytes([f[12], f[13]]);
        match (ethertype, f.get(23)) {
            (0x0806, _) => {
                self.arp += 1;
                if self.arp_logged < 12 && f.len() >= 42 {
                    self.arp_logged += 1;
                    hal::log!(
                        "net: {dir} ARP {} from {:02x?} {}.{}.{}.{} to {}.{}.{}.{} (frame {:02x?} -> {:02x?})",
                        if f[21] == 1 { "request" } else { "reply" },
                        &f[22..28],
                        f[28], f[29], f[30], f[31],
                        f[38], f[39], f[40], f[41],
                        &f[6..12],
                        &f[0..6]
                    );
                }
            }
            (0x0800, Some(17)) => self.udp += 1,
            (0x0800, Some(6)) => self.tcp += 1,
            _ => {
                self.other += 1;
                if let Some(slot) = self.types.iter_mut().find(|(t, _)| *t == ethertype || *t == 0) {
                    slot.0 = ethertype;
                    slot.1 += 1;
                }
            }
        }
    }
}

struct Adapter {
    dev: Box<dyn NetDevice>,
    rx: Counts,
    tx: Counts,
    /// While probing a leased address: the address being watched, and the MAC of anyone else
    /// seen using it (an ARP reply or probe naming the same IP).
    watch_ip: Option<[u8; 4]>,
    conflict: Option<[u8; 6]>,
}

struct RxTok(Vec<u8>);
struct TxTok<'a>(&'a mut dyn NetDevice, &'a mut Counts);

impl phy::RxToken for RxTok {
    fn consume<R, F: FnOnce(&[u8]) -> R>(self, f: F) -> R {
        f(&self.0)
    }
}

impl phy::TxToken for TxTok<'_> {
    fn consume<R, F: FnOnce(&mut [u8]) -> R>(self, len: usize, f: F) -> R {
        let mut buf = vec![0u8; len];
        let r = f(&mut buf);
        self.1.note("sent", &buf);
        let _ = self.0.transmit(&buf);
        r
    }
}

impl Device for Adapter {
    type RxToken<'a> = RxTok;
    type TxToken<'a> = TxTok<'a>;

    fn receive(&mut self, _ts: Instant) -> Option<(RxTok, TxTok<'_>)> {
        let mut buf = vec![0u8; MTU + 4];
        let n = self.dev.receive(&mut buf)?;
        buf.truncate(n);
        self.rx.note("received", &buf);
        if let Some(ip) = self.watch_ip {
            // ARP: [14..22] fixed fields, sender MAC [22..28], sender IP [28..32], target IP [38..42].
            if buf.len() >= 42 && buf[12..14] == [0x08, 0x06] {
                let (sender_ip, target_ip) = (&buf[28..32], &buf[38..42]);
                let probe = sender_ip == [0u8; 4] && target_ip == ip;
                if (sender_ip == ip || probe) && buf[22..28] != self.dev.mac() {
                    self.conflict = Some(buf[22..28].try_into().unwrap());
                }
            }
        }
        Some((RxTok(buf), TxTok(self.dev.as_mut(), &mut self.tx)))
    }

    fn transmit(&mut self, _ts: Instant) -> Option<TxTok<'_>> {
        Some(TxTok(self.dev.as_mut(), &mut self.tx))
    }

    fn capabilities(&self) -> DeviceCapabilities {
        let mut c = DeviceCapabilities::default();
        c.medium = Medium::Ethernet;
        c.max_transmission_unit = MTU;
        c
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Lease {
    pub address: [u8; 4],
    pub prefix: u8,
    pub router: Option<[u8; 4]>,
    pub dns: Option<[u8; 4]>,
}

pub struct Stack {
    dev: Adapter,
    iface: Interface,
    sockets: SocketSet<'static>,
    dhcp: SocketHandle,
    dns: SocketHandle,
    now_ms: fn() -> u64,
    next_port: u16,
    gateway: Option<[u8; 4]>,
    dns_servers: Vec<[u8; 4]>,
    /// Resolvers in the order tried: the DHCP-provided ones, then `FALLBACK_DNS`.
    resolvers: Vec<[u8; 4]>,
    /// Index into `resolvers` of the one that answered last; lookups start there.
    resolver: usize,
}

impl Stack {
    /// `now_ms` must be monotonic; `seed` should differ per boot.
    pub fn new(dev: Box<dyn NetDevice>, now_ms: fn() -> u64, seed: u64) -> Stack {
        let mac = dev.mac();
        let mut dev = Adapter { dev, rx: Counts::default(), tx: Counts::default(), watch_ip: None, conflict: None };
        let mut cfg = Config::new(HardwareAddress::Ethernet(EthernetAddress(mac)));
        cfg.random_seed = seed;
        let iface = Interface::new(cfg, &mut dev, Instant::from_millis(now_ms() as i64));
        let mut sockets = SocketSet::new(Vec::new());
        let dhcp = sockets.add(dhcpv4::Socket::new());
        let dns = sockets.add(dns::Socket::new(&[], [None, None]));
        Stack {
            dev,
            iface,
            sockets,
            dhcp,
            dns,
            now_ms,
            next_port: 49152 + (seed % 10000) as u16,
            gateway: None,
            dns_servers: Vec::new(),
            resolvers: Vec::new(),
            resolver: 0,
        }
    }

    fn now(&self) -> Instant {
        Instant::from_millis((self.now_ms)() as i64)
    }

    pub fn poll(&mut self) {
        let now = self.now();
        self.iface.poll(now, &mut self.dev, &mut self.sockets);
    }

    pub fn link_up(&mut self) -> bool {
        self.dev.dev.link_up()
    }

    /// The stack's millisecond clock, for diagnostics (a plain function, so it can be kept while a
    /// connection borrows the stack).
    pub fn clock(&self) -> fn() -> u64 {
        self.now_ms
    }

    fn deadline(&self, timeout_ms: u64) -> u64 {
        (self.now_ms)() + timeout_ms
    }

    /// Runs DHCP until a lease is acquired and applies it to the interface.
    pub fn dhcp(&mut self, timeout_ms: u64) -> Result<Lease> {
        let mut end = self.deadline(timeout_ms);
        let mut declined = 0;
        while (self.now_ms)() < end {
            self.poll();
            let ev = self.sockets.get_mut::<dhcpv4::Socket>(self.dhcp).poll();
            if let Some(dhcpv4::Event::Configured(c)) = ev {
                // Copy what is needed so the socket borrow ends here.
                let (cidr, router, server) = (c.address, c.router, c.server);
                let dhcp_dns: Vec<Ipv4Address> = c.dns_servers.iter().copied().collect();
                let ip = cidr.address().octets();

                // Before using the address, check that nobody else does (RFC 5227), as Linux's DHCP
                // clients do. A static host inside the DHCP pool made every reply to us go to it
                // (seen on a school network); the right response is to decline and ask for another.
                if declined >= MAX_DECLINES {
                    hal::info!("net: the DHCP server keeps offering addresses that are in use; using {}.{}.{}.{} anyway", ip[0], ip[1], ip[2], ip[3]);
                } else {
                    if let Some(mac) = self.probe_address(ip) {
                        hal::info!(
                            "net: {}.{}.{}.{} is already in use by {:02x?}: declining it and asking the DHCP server again",
                            ip[0], ip[1], ip[2], ip[3], mac
                        );
                        self.dhcp_decline(ip, server.identifier.octets());
                        declined += 1;
                        self.sockets.get_mut::<dhcpv4::Socket>(self.dhcp).reset();
                        // The server needs a moment to mark the address bad before it offers again.
                        let wait = (self.now_ms)() + 3000;
                        while (self.now_ms)() < wait {
                            self.poll();
                            hal::idle();
                        }
                        end = self.deadline(timeout_ms);
                        continue;
                    }
                }
                let lease = Lease {
                    address: ip,
                    prefix: cidr.prefix_len(),
                    router: router.map(|r| r.octets()),
                    dns: dhcp_dns.first().map(|d| d.octets()),
                };
                let mut dns: Vec<[u8; 4]> = dhcp_dns.iter().map(|d| d.octets()).collect();
                // Some networks hand out a resolver that never answers us (found on a campus network);
                // fall back to public ones after the DHCP-provided servers (`resolve` tries them in turn).
                for fallback in FALLBACK_DNS {
                    if !dns.contains(&fallback) {
                        dns.push(fallback);
                    }
                }
                hal::log!("net: DNS servers {:?}", dns.iter().map(|d| alloc::format!("{}.{}.{}.{}", d[0], d[1], d[2], d[3])).collect::<Vec<_>>());
                hal::log!("net: DHCP server {} (identifier {}), declined {declined} address(es)", server.address, server.identifier);
                self.gateway = router.map(|r| r.octets());
                self.dns_servers = dhcp_dns.iter().map(|d| d.octets()).collect();
                self.iface.update_ip_addrs(|a| {
                    a.clear();
                    let _ = a.push(IpCidr::Ipv4(cidr));
                });
                if let Some(r) = router {
                    let _ = self.iface.routes_mut().add_default_ipv4_route(r);
                }
                self.resolvers = dns;
                self.resolver = 0;
                // Announce the address with a gratuitous ARP, as Linux's DHCP clients do, so switches
                // and gateways learn this MAC/IP pairing before they see any other traffic from it.
                self.announce(lease.address);
                return Ok(lease);
            }
            hal::idle();
        }
        Err(Error::Timeout)
    }

    /// ARP-probes `ip` (RFC 5227: three probes with sender address 0.0.0.0, then a short wait) and
    /// returns the MAC of any other host that answers for it or probes for it too.
    fn probe_address(&mut self, ip: [u8; 4]) -> Option<[u8; 6]> {
        let mac = self.dev.dev.mac();
        let mut f = [0u8; 42];
        f[0..6].fill(0xff);
        f[6..12].copy_from_slice(&mac);
        f[12..14].copy_from_slice(&0x0806u16.to_be_bytes());
        f[14..22].copy_from_slice(&[0, 1, 8, 0, 6, 4, 0, 1]);
        f[22..28].copy_from_slice(&mac);
        // sender IP stays 0.0.0.0, target hardware address zero
        f[38..42].copy_from_slice(&ip);
        self.dev.watch_ip = Some(ip);
        self.dev.conflict = None;
        let start = (self.now_ms)();
        let mut sent = 0u64;
        while (self.now_ms)() - start < PROBE_MS && self.dev.conflict.is_none() {
            if sent < 3 && (self.now_ms)() - start >= sent * 300 {
                self.dev.tx.note("sent", &f);
                let _ = self.dev.dev.transmit(&f);
                sent += 1;
            }
            self.poll();
            hal::idle();
        }
        self.dev.watch_ip = None;
        self.dev.conflict.take()
    }

    /// DHCPDECLINE for `ip` to the server `server`: tells it the address is in use.
    fn dhcp_decline(&mut self, ip: [u8; 4], server: [u8; 4]) {
        let mac = self.dev.dev.mac();
        let mut bootp = vec![0u8; 236];
        bootp[0] = 1; // BOOTREQUEST
        bootp[1] = 1; // Ethernet
        bootp[2] = 6;
        bootp[4..8].copy_from_slice(&((self.now_ms)() as u32 ^ 0x5a5a_a5a5).to_be_bytes()); // xid
        bootp[28..34].copy_from_slice(&mac); // chaddr
        bootp.extend_from_slice(&[99, 130, 83, 99]); // magic cookie
        bootp.extend_from_slice(&[53, 1, 4]); // DHCPDECLINE
        bootp.extend_from_slice(&[50, 4]);
        bootp.extend_from_slice(&ip); // requested address
        bootp.extend_from_slice(&[54, 4]);
        bootp.extend_from_slice(&server); // server identifier
        bootp.extend_from_slice(&[61, 7, 1]);
        bootp.extend_from_slice(&mac); // client identifier
        bootp.push(255);
        let udp_len = 8 + bootp.len();
        let ip_len = 20 + udp_len;
        let mut f = Vec::with_capacity(14 + ip_len);
        f.extend_from_slice(&[0xff; 6]);
        f.extend_from_slice(&mac);
        f.extend_from_slice(&0x0800u16.to_be_bytes());
        let ip_start = f.len();
        f.extend_from_slice(&[0x45, 0, (ip_len >> 8) as u8, ip_len as u8, 0, 0, 0, 0, 64, 17, 0, 0]);
        f.extend_from_slice(&[0, 0, 0, 0]); // source 0.0.0.0
        f.extend_from_slice(&[255, 255, 255, 255]);
        let mut sum = 0u32;
        for w in f[ip_start..ip_start + 20].chunks(2) {
            sum += u16::from_be_bytes([w[0], w[1]]) as u32;
        }
        while sum >> 16 != 0 {
            sum = (sum & 0xffff) + (sum >> 16);
        }
        let ck = !(sum as u16);
        f[ip_start + 10..ip_start + 12].copy_from_slice(&ck.to_be_bytes());
        f.extend_from_slice(&68u16.to_be_bytes());
        f.extend_from_slice(&67u16.to_be_bytes());
        f.extend_from_slice(&(udp_len as u16).to_be_bytes());
        f.extend_from_slice(&[0, 0]); // UDP checksum omitted (allowed for IPv4)
        f.extend_from_slice(&bootp);
        self.dev.tx.note("sent", &f);
        let _ = self.dev.dev.transmit(&f);
    }


    /// Resolves an IPv4 address (dotted quads are parsed directly). The resolvers are tried one at a
    /// time, starting with the one that answered last, each with an equal share of the time left:
    /// smoltcp would only move on to the next server after 10 s, longer than a whole lookup may take.
    pub fn resolve(&mut self, name: &str, timeout_ms: u64) -> Result<[u8; 4]> {
        if let Some(ip) = parse_ipv4(name) {
            return Ok(ip);
        }
        let n = self.resolvers.len();
        if n == 0 {
            return Err(Error::Dns);
        }
        let end = self.deadline(timeout_ms);
        let mut last = Error::Timeout;
        for k in 0..n {
            let now = (self.now_ms)();
            if now >= end {
                break;
            }
            let i = (self.resolver + k) % n;
            let server = self.resolvers[i];
            match self.query(name, server, now + (end - now) / (n - k) as u64) {
                Ok(ip) => {
                    if i != self.resolver {
                        hal::info!("net: DNS server {}.{}.{}.{} answered; using it from now on", server[0], server[1], server[2], server[3]);
                        self.resolver = i;
                    }
                    return Ok(ip);
                }
                Err(e) => {
                    hal::log!("net: DNS server {}.{}.{}.{} gave no answer for {name}: {e:?}", server[0], server[1], server[2], server[3]);
                    last = e;
                }
            }
        }
        hal::info!("net: DNS query for {name} unanswered; {}", self.counters());
        Err(last)
    }

    /// One lookup of `name` at `server`, given up at `until` (ms).
    fn query(&mut self, name: &str, server: [u8; 4], until: u64) -> Result<[u8; 4]> {
        let sock = self.sockets.get_mut::<dns::Socket>(self.dns);
        sock.update_servers(&[IpAddress::Ipv4(Ipv4Address::from(server))]);
        let h = sock.start_query(self.iface.context(), name, DnsQueryType::A).map_err(|_| Error::Dns)?;
        while (self.now_ms)() < until {
            self.poll();
            match self.sockets.get_mut::<dns::Socket>(self.dns).get_query_result(h) {
                Ok(addrs) => {
                    return match addrs.first() {
                        Some(IpAddress::Ipv4(v4)) => Ok(v4.octets()),
                        None => Err(Error::Dns),
                    };
                }
                Err(dns::GetQueryResultError::Pending) => hal::idle(),
                Err(_) => return Err(Error::Dns),
            }
        }
        self.sockets.get_mut::<dns::Socket>(self.dns).cancel_query(h);
        Err(Error::Timeout)
    }

    /// Gratuitous ARP for `ip` (an ARP request for our own address).
    fn announce(&mut self, ip: [u8; 4]) {
        let mac = self.dev.dev.mac();
        let mut f = [0u8; 42];
        f[0..6].fill(0xff);
        f[6..12].copy_from_slice(&mac);
        f[12..14].copy_from_slice(&0x0806u16.to_be_bytes());
        f[14..22].copy_from_slice(&[0, 1, 8, 0, 6, 4, 0, 1]);
        f[22..28].copy_from_slice(&mac);
        f[28..32].copy_from_slice(&ip);
        f[38..42].copy_from_slice(&ip);
        self.dev.tx.note("sent", &f);
        let _ = self.dev.dev.transmit(&f);
    }

    /// The default gateway from the DHCP lease.
    pub fn gateway(&self) -> Option<[u8; 4]> {
        self.gateway
    }

    /// The DHCP-provided DNS servers (without the built-in fallbacks).
    pub fn dhcp_dns(&self) -> &[[u8; 4]] {
        &self.dns_servers
    }

    /// ICMP echo to `ip`; returns the round-trip time in ms if a reply came back in time.
    pub fn ping(&mut self, ip: [u8; 4], timeout_ms: u64) -> Option<u64> {
        use smoltcp::phy::ChecksumCapabilities;
        use smoltcp::socket::icmp;
        use smoltcp::wire::{Icmpv4Packet, Icmpv4Repr};
        let rx = icmp::PacketBuffer::new(vec![icmp::PacketMetadata::EMPTY; 2], vec![0; 256]);
        let tx = icmp::PacketBuffer::new(vec![icmp::PacketMetadata::EMPTY; 2], vec![0; 256]);
        let h = self.sockets.add(icmp::Socket::new(rx, tx));
        let ident = 0x4152;
        let dst = IpAddress::Ipv4(Ipv4Address::from(ip));
        let caps = ChecksumCapabilities::default();
        let result = (|| {
            let sock = self.sockets.get_mut::<icmp::Socket>(h);
            sock.bind(icmp::Endpoint::Ident(ident)).ok()?;
            let repr = Icmpv4Repr::EchoRequest { ident, seq_no: 1, data: b"archstaller" };
            let buf = sock.send(repr.buffer_len(), dst).ok()?;
            repr.emit(&mut Icmpv4Packet::new_unchecked(buf), &caps);
            let start = (self.now_ms)();
            while (self.now_ms)() - start < timeout_ms {
                self.poll();
                let sock = self.sockets.get_mut::<icmp::Socket>(h);
                if sock.can_recv() {
                    let (payload, _) = sock.recv().ok()?;
                    let pkt = Icmpv4Packet::new_checked(payload).ok()?;
                    if matches!(Icmpv4Repr::parse(&pkt, &caps), Ok(Icmpv4Repr::EchoReply { ident: i, .. }) if i == ident) {
                        return Some((self.now_ms)() - start);
                    }
                }
                hal::idle();
            }
            None
        })();
        self.sockets.remove(h);
        result
    }

    /// Frames sent and received so far, by kind (diagnostics).
    pub fn counters(&self) -> alloc::string::String {
        let (r, t) = (&self.dev.rx, &self.dev.tx);
        let types: alloc::vec::Vec<alloc::string::String> =
            r.types.iter().filter(|(t, _)| *t != 0).map(|(t, n)| alloc::format!("{t:04x}x{n}")).collect();
        alloc::format!(
            "rx: {} arp, {} udp, {} tcp, {} other ({} unicast; other ethertypes {:?}); tx: {} arp, {} udp, {} tcp, {} other",
            r.arp, r.udp, r.tcp, r.other, r.unicast, types, t.arp, t.udp, t.tcp, t.other
        )
    }

    pub fn connect(&mut self, ip: [u8; 4], port: u16, timeout_ms: u64) -> Result<TcpConn<'_>> {
        let sock = tcp::Socket::new(tcp::SocketBuffer::new(vec![0; TCP_RX]), tcp::SocketBuffer::new(vec![0; TCP_TX]));
        let handle = self.sockets.add(sock);
        let local = self.next_port;
        self.next_port = if self.next_port >= 60000 { 49152 } else { self.next_port + 1 };
        let remote = IpEndpoint::new(IpAddress::Ipv4(Ipv4Address::from(ip)), port);
        let s = self.sockets.get_mut::<tcp::Socket>(handle);
        s.set_nagle_enabled(false);
        if s.connect(self.iface.context(), remote, local).is_err() {
            self.sockets.remove(handle);
            return Err(Error::Connect);
        }
        let mut conn = TcpConn { stack: self, handle, timeout_ms: 30_000 };
        let end = conn.stack.deadline(timeout_ms);
        loop {
            conn.stack.poll();
            match conn.sock().state() {
                tcp::State::Established => return Ok(conn),
                tcp::State::Closed => return Err(Error::Connect),
                _ => {}
            }
            if (conn.stack.now_ms)() >= end {
                return Err(Error::Timeout);
            }
            hal::idle();
        }
    }
}

fn parse_ipv4(s: &str) -> Option<[u8; 4]> {
    let mut out = [0u8; 4];
    let mut parts = s.split('.');
    for o in out.iter_mut() {
        *o = parts.next()?.parse().ok()?;
    }
    if parts.next().is_some() {
        return None;
    }
    Some(out)
}

pub struct TcpConn<'a> {
    stack: &'a mut Stack,
    handle: SocketHandle,
    /// Idle timeout for blocking reads and writes.
    pub timeout_ms: u64,
}

impl TcpConn<'_> {
    fn sock(&mut self) -> &mut tcp::Socket<'static> {
        self.stack.sockets.get_mut::<tcp::Socket>(self.handle)
    }

    pub fn close(&mut self) {
        self.sock().close();
        let end = self.stack.deadline(2000);
        while (self.stack.now_ms)() < end && self.sock().is_active() {
            self.stack.poll();
            hal::idle();
        }
    }
}

impl Stream for TcpConn<'_> {
    fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
        let end = self.stack.deadline(self.timeout_ms);
        loop {
            self.stack.poll();
            let s = self.sock();
            if s.can_recv() {
                return s.recv_slice(buf).map_err(|_| Error::Closed);
            }
            if !s.may_recv() {
                return Ok(0);
            }
            if (self.stack.now_ms)() >= end {
                return Err(Error::Timeout);
            }
            hal::idle();
        }
    }

    fn write_all(&mut self, mut buf: &[u8]) -> Result<()> {
        let mut end = self.stack.deadline(self.timeout_ms);
        while !buf.is_empty() {
            self.stack.poll();
            let s = self.sock();
            if !s.may_send() {
                return Err(Error::Closed);
            }
            if s.can_send() {
                let n = s.send_slice(buf).map_err(|_| Error::Closed)?;
                buf = &buf[n..];
                end = self.stack.deadline(self.timeout_ms);
            } else if (self.stack.now_ms)() >= end {
                return Err(Error::Timeout);
            } else {
                hal::idle();
            }
        }
        // Push out what is queued.
        self.stack.poll();
        Ok(())
    }
}

impl Drop for TcpConn<'_> {
    fn drop(&mut self) {
        self.sock().abort();
        self.stack.poll();
        self.stack.sockets.remove(self.handle);
    }
}

#[cfg(test)]
mod tests {
    extern crate std;
    use super::*;
    use core::sync::atomic::{AtomicU64, Ordering};
    use smoltcp::phy::ChecksumCapabilities;
    use smoltcp::wire::{DhcpMessageType, DhcpPacket, DhcpRepr, EthernetFrame, EthernetProtocol, IpProtocol, Ipv4Packet, Ipv4Repr, UdpPacket, UdpRepr};
    use std::cell::RefCell;
    use std::rc::Rc;

    static CLOCK: AtomicU64 = AtomicU64::new(0);
    /// A clock that moves 5 ms per reading, so loops that wait for time terminate.
    fn clock() -> u64 {
        CLOCK.fetch_add(5, Ordering::Relaxed)
    }

    #[derive(Default)]
    struct Wire {
        sent: std::vec::Vec<std::vec::Vec<u8>>,
        /// Frames to hand back from `receive`, one per call.
        inbox: std::collections::VecDeque<std::vec::Vec<u8>>,
        /// When set, every ARP request is answered with this MAC.
        arp_mac: Option<[u8; 6]>,
        /// When set, DNS queries sent to the first address are answered with the second.
        dns: Option<([u8; 4], [u8; 4])>,
    }

    impl Wire {
        /// Answers what `frame` asks for, as configured.
        fn respond(&mut self, f: &[u8]) {
            if let Some(mac) = self.arp_mac {
                if f.len() >= 42 && f[12..14] == [0x08, 0x06] && f[20..22] == [0, 1] {
                    let mut r = arp_frame(mac, f[38..42].try_into().unwrap(), f[28..32].try_into().unwrap());
                    r[0..6].copy_from_slice(&f[6..12]);
                    r[32..38].copy_from_slice(&f[22..28]);
                    self.inbox.push_back(r);
                }
            }
            let Some((server, answer)) = self.dns else { return };
            let Ok(eth) = EthernetFrame::new_checked(f) else { return };
            let Ok(ip) = Ipv4Packet::new_checked(eth.payload()) else { return };
            if eth.ethertype() != EthernetProtocol::Ipv4 || ip.next_header() != IpProtocol::Udp || ip.dst_addr().octets() != server {
                return;
            }
            let Ok(udp) = UdpPacket::new_checked(ip.payload()) else { return };
            if udp.dst_port() != 53 {
                return;
            }
            // The query with the response flags, one answer count and an A record for the question's name.
            let mut dns = udp.payload().to_vec();
            dns[2..4].copy_from_slice(&[0x81, 0x80]);
            dns[6..8].copy_from_slice(&1u16.to_be_bytes());
            dns.extend_from_slice(&[0xc0, 0x0c, 0, 1, 0, 1, 0, 0, 0, 60, 0, 4]);
            dns.extend_from_slice(&answer);
            let caps = ChecksumCapabilities::default();
            let mut r = std::vec![0u8; 14 + 20 + 8 + dns.len()];
            r[0..6].copy_from_slice(&f[6..12]);
            r[6..12].copy_from_slice(&f[0..6]);
            r[12..14].copy_from_slice(&0x0800u16.to_be_bytes());
            let (src, dst) = (ip.dst_addr(), ip.src_addr());
            Ipv4Repr { src_addr: src, dst_addr: dst, next_header: IpProtocol::Udp, payload_len: 8 + dns.len(), hop_limit: 64 }
                .emit(&mut Ipv4Packet::new_unchecked(&mut r[14..]), &caps);
            UdpRepr { src_port: 53, dst_port: udp.src_port() }.emit(
                &mut UdpPacket::new_unchecked(&mut r[34..]),
                &IpAddress::Ipv4(src),
                &IpAddress::Ipv4(dst),
                dns.len(),
                |b| b.copy_from_slice(&dns),
                &caps,
            );
            self.inbox.push_back(r);
        }

        /// Destination addresses of the DNS queries sent so far, in order.
        fn dns_queries(&self) -> std::vec::Vec<[u8; 4]> {
            self.sent
                .iter()
                .filter_map(|f| {
                    let ip = Ipv4Packet::new_checked(EthernetFrame::new_checked(&f[..]).ok()?.payload()).ok()?;
                    let udp = UdpPacket::new_checked(ip.payload()).ok()?;
                    (ip.next_header() == IpProtocol::Udp && udp.dst_port() == 53).then(|| ip.dst_addr().octets())
                })
                .collect()
        }
    }

    struct Mock(Rc<RefCell<Wire>>);

    impl NetDevice for Mock {
        fn name(&self) -> &str {
            "mock"
        }
        fn mac(&self) -> [u8; 6] {
            [2, 0, 0, 0, 0, 1]
        }
        fn link_up(&mut self) -> bool {
            true
        }
        fn transmit(&mut self, frame: &[u8]) -> hal::Result<()> {
            let mut w = self.0.borrow_mut();
            w.sent.push(frame.to_vec());
            w.respond(frame);
            Ok(())
        }
        fn receive(&mut self, buf: &mut [u8]) -> Option<usize> {
            let f = self.0.borrow_mut().inbox.pop_front()?;
            buf[..f.len()].copy_from_slice(&f);
            Some(f.len())
        }
    }

    fn arp_frame(sender_mac: [u8; 6], sender_ip: [u8; 4], target_ip: [u8; 4]) -> std::vec::Vec<u8> {
        let mut f = std::vec![0u8; 42];
        f[0..6].fill(0xff);
        f[6..12].copy_from_slice(&sender_mac);
        f[12..14].copy_from_slice(&0x0806u16.to_be_bytes());
        f[14..22].copy_from_slice(&[0, 1, 8, 0, 6, 4, 0, 2]);
        f[22..28].copy_from_slice(&sender_mac);
        f[28..32].copy_from_slice(&sender_ip);
        f[38..42].copy_from_slice(&target_ip);
        f
    }

    fn stack() -> (Stack, Rc<RefCell<Wire>>) {
        let wire = Rc::new(RefCell::new(Wire::default()));
        (Stack::new(Box::new(Mock(wire.clone())), clock, 7), wire)
    }

    #[test]
    fn decline_frame_is_a_valid_dhcp_decline() {
        let (mut s, wire) = stack();
        s.dhcp_decline([10, 21, 14, 2], [10, 21, 14, 1]);
        let w = wire.borrow();
        let f = w.sent.last().expect("decline sent");
        let eth = EthernetFrame::new_checked(&f[..]).unwrap();
        assert_eq!(eth.ethertype(), EthernetProtocol::Ipv4);
        let ip = Ipv4Packet::new_checked(eth.payload()).unwrap();
        assert!(ip.verify_checksum(), "IP header checksum");
        assert_eq!(ip.next_header(), IpProtocol::Udp);
        let udp = UdpPacket::new_checked(ip.payload()).unwrap();
        assert_eq!((udp.src_port(), udp.dst_port()), (68, 67));
        let dhcp = DhcpPacket::new_checked(udp.payload()).unwrap();
        let repr = DhcpRepr::parse(&dhcp).unwrap();
        assert_eq!(repr.message_type, DhcpMessageType::Decline);
        assert_eq!(repr.requested_ip, Some(Ipv4Address::new(10, 21, 14, 2)));
        assert_eq!(repr.server_identifier, Some(Ipv4Address::new(10, 21, 14, 1)));
        assert_eq!(repr.client_hardware_address, EthernetAddress([2, 0, 0, 0, 0, 1]));
    }

    #[test]
    fn probe_sees_another_host_using_the_address() {
        let (mut s, wire) = stack();
        // Someone else answers the probe for 10.21.14.2.
        wire.borrow_mut().inbox.push_back(arp_frame([0x5c, 0xf9, 0xdd, 0x55, 0x07, 0x0c], [10, 21, 14, 2], [10, 21, 14, 2]));
        assert_eq!(s.probe_address([10, 21, 14, 2]), Some([0x5c, 0xf9, 0xdd, 0x55, 0x07, 0x0c]));
        // The probe itself: ARP request, sender IP 0.0.0.0, target the probed address.
        let w = wire.borrow();
        let p = &w.sent[0];
        assert_eq!(&p[12..14], &[0x08, 0x06]);
        assert_eq!(&p[28..32], &[0, 0, 0, 0]);
        assert_eq!(&p[38..42], &[10, 21, 14, 2]);
    }

    #[test]
    fn probe_ignores_unrelated_and_own_arp() {
        let (mut s, wire) = stack();
        // An ARP about another address, and our own MAC echoed back.
        wire.borrow_mut().inbox.push_back(arp_frame([0x5c, 0, 0, 0, 0, 9], [10, 21, 14, 7], [10, 21, 14, 7]));
        wire.borrow_mut().inbox.push_back(arp_frame([2, 0, 0, 0, 0, 1], [10, 21, 14, 2], [10, 21, 14, 2]));
        assert_eq!(s.probe_address([10, 21, 14, 2]), None);
        // (The stack's own DHCP socket may also have sent a DISCOVER meanwhile; count only the probes.)
        let probes = wire.borrow().sent.iter().filter(|f| f[12..14] == [0x08, 0x06] && f[28..32] == [0, 0, 0, 0]).count();
        assert_eq!(probes, 3, "three ARP probes were sent");
    }

    #[test]
    fn resolve_falls_back_to_the_next_server_and_keeps_using_it() {
        let (mut s, wire) = stack();
        s.iface.update_ip_addrs(|a| {
            let _ = a.push(IpCidr::new(IpAddress::v4(10, 0, 0, 2), 24));
        });
        let _ = s.iface.routes_mut().add_default_ipv4_route(Ipv4Address::new(10, 0, 0, 1));
        // The DHCP-provided resolver never answers; the first fallback does.
        s.resolvers = std::vec![[10, 0, 0, 53], [1, 1, 1, 1], [8, 8, 8, 8]];
        {
            let mut w = wire.borrow_mut();
            w.arp_mac = Some([2, 0, 0, 0, 0, 0xfe]);
            w.dns = Some(([1, 1, 1, 1], [93, 184, 216, 34]));
        }
        assert_eq!(s.resolve("mirror.example.org", 6000), Ok([93, 184, 216, 34]));
        let q = wire.borrow().dns_queries();
        assert_eq!(q.first(), Some(&[10, 0, 0, 53]), "the DHCP-provided server is asked first");
        assert_eq!(q.last(), Some(&[1, 1, 1, 1]));
        assert!(!q.contains(&[8, 8, 8, 8]), "no need to ask the second fallback");

        // The next lookup goes straight to the server that answered.
        wire.borrow_mut().sent.clear();
        assert_eq!(s.resolve("mirror.example.org", 6000), Ok([93, 184, 216, 34]));
        assert_eq!(wire.borrow().dns_queries(), std::vec![[1, 1, 1, 1]]);
    }

    #[test]
    fn resolve_without_any_answer_times_out_after_asking_every_server() {
        let (mut s, wire) = stack();
        s.iface.update_ip_addrs(|a| {
            let _ = a.push(IpCidr::new(IpAddress::v4(10, 0, 0, 2), 24));
        });
        let _ = s.iface.routes_mut().add_default_ipv4_route(Ipv4Address::new(10, 0, 0, 1));
        s.resolvers = std::vec![[10, 0, 0, 53], [1, 1, 1, 1]];
        wire.borrow_mut().arp_mac = Some([2, 0, 0, 0, 0, 0xfe]);
        assert_eq!(s.resolve("mirror.example.org", 6000), Err(Error::Timeout));
        let mut q = wire.borrow().dns_queries();
        q.dedup();
        assert_eq!(q, std::vec![[10, 0, 0, 53], [1, 1, 1, 1]]);
    }
}

}
pub mod tls {
//! TLS 1.2/1.3 client over any [`Stream`], using rustls' unbuffered API and the RustCrypto provider.
use crate::__archstaler_source::{Error, Result, Stream};
use alloc::string::String;
use alloc::sync::Arc;
use alloc::vec::Vec;
use core::time::Duration;
use rustls::client::UnbufferedClientConnection;
use rustls::pki_types::{ServerName, UnixTime};
use rustls::time_provider::TimeProvider;
use rustls::unbuffered::{ConnectionState, EncodeError, EncryptError, UnbufferedStatus};
use rustls::{ClientConfig, RootCertStore};

/// TSC cycles spent decrypting/processing TLS records, and waiting for bytes from the transport.
/// Diagnostics for the hardware test's speed report.
pub static CRYPTO_TSC: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);
pub static IO_TSC: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

fn tsc() -> u64 {
    unsafe { core::arch::x86_64::_rdtsc() }
}

fn add(counter: &core::sync::atomic::AtomicU64, since: u64) {
    counter.fetch_add(tsc().wrapping_sub(since), core::sync::atomic::Ordering::Relaxed);
}

#[derive(Debug)]
struct WallClock(fn() -> u64);

impl TimeProvider for WallClock {
    fn current_time(&self) -> Option<UnixTime> {
        Some(UnixTime::since_unix_epoch(Duration::from_secs((self.0)())))
    }
}

/// Builds a client config trusting the bundled Mozilla roots. `unix_time` supplies the wall clock
/// for certificate validity checks.
pub fn client_config(unix_time: fn() -> u64) -> Arc<ClientConfig> {
    let mut roots = RootCertStore::empty();
    roots.roots.extend(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
    let cfg = ClientConfig::builder_with_details(Arc::new(rustls_rustcrypto::provider()), Arc::new(WallClock(unix_time)))
        .with_safe_default_protocol_versions()
        .expect("provider supports default TLS versions")
        .with_root_certificates(roots)
        .with_no_client_auth();
    Arc::new(cfg)
}

pub struct TlsStream<S: Stream> {
    inner: S,
    conn: UnbufferedClientConnection,
    /// Received TLS bytes not yet consumed by rustls.
    incoming: Vec<u8>,
    /// Scratch for records to send.
    outgoing: Vec<u8>,
    /// Decrypted data not yet handed to the caller.
    plaintext: Vec<u8>,
    plain_pos: usize,
    eof: bool,
}

enum Step {
    Continue,
    NeedData,
    HandshakeDone,
    Eof,
}

const MAX_RECORD: usize = 16 * 1024;

impl<S: Stream> TlsStream<S> {
    /// Connects and completes the handshake.
    pub fn connect(inner: S, config: Arc<ClientConfig>, server_name: &str) -> Result<Self> {
        let name = ServerName::try_from(String::from(server_name)).map_err(|_| Error::Http("bad server name"))?;
        let conn = UnbufferedClientConnection::new(config, name).map_err(|_| Error::Http("tls setup"))?;
        let mut t = TlsStream {
            inner,
            conn,
            incoming: Vec::new(),
            outgoing: alloc::vec![0; MAX_RECORD + 512],
            plaintext: Vec::new(),
            plain_pos: 0,
            eof: false,
        };
        loop {
            match t.step(true)? {
                Step::HandshakeDone => return Ok(t),
                // A peer that closed mid-handshake would otherwise be read (0 bytes) forever.
                Step::Eof => return Err(Error::Closed),
                Step::NeedData if t.eof => return Err(Error::Closed),
                Step::NeedData => t.fill()?,
                Step::Continue => {}
            }
        }
    }

    fn fill(&mut self) -> Result<()> {
        let mut tmp = [0u8; 16384];
        let t0 = tsc();
        let n = self.inner.read(&mut tmp);
        add(&IO_TSC, t0);
        let n = n?;
        if n == 0 {
            self.eof = true;
        }
        self.incoming.extend_from_slice(&tmp[..n]);
        Ok(())
    }

    /// Runs the state machine once.
    fn step(&mut self, handshaking: bool) -> Result<Step> {
        let t0 = tsc();
        let UnbufferedStatus { discard, state } = self.conn.process_tls_records(&mut self.incoming);
        let state = state.map_err(|_| Error::Http("tls error"))?;
        let mut to_send = 0usize;
        let mut plain: Vec<u8> = Vec::new();
        let mut extra_discard = 0usize;
        let step = match state {
            ConnectionState::EncodeTlsData(mut e) => {
                match e.encode(&mut self.outgoing) {
                    Ok(n) => to_send = n,
                    Err(EncodeError::InsufficientSize(s)) => {
                        self.outgoing.resize(s.required_size, 0);
                        // Retry after resizing; the chunk is kept by rustls on this error.
                        match e.encode(&mut self.outgoing) {
                            Ok(n) => to_send = n,
                            Err(_) => return Err(Error::Http("tls encode")),
                        }
                    }
                    Err(_) => return Err(Error::Http("tls encode")),
                }
                Step::Continue
            }
            ConnectionState::TransmitTlsData(t) => {
                t.done();
                Step::Continue
            }
            ConnectionState::BlockedHandshake => Step::NeedData,
            ConnectionState::WriteTraffic(_) => {
                if handshaking {
                    Step::HandshakeDone
                } else {
                    Step::NeedData
                }
            }
            ConnectionState::ReadTraffic(mut r) => {
                while let Some(rec) = r.next_record() {
                    let rec = rec.map_err(|_| Error::Http("tls record"))?;
                    plain.extend_from_slice(rec.payload);
                    extra_discard += rec.discard;
                }
                Step::Continue
            }
            ConnectionState::PeerClosed | ConnectionState::Closed => Step::Eof,
            _ => Step::Continue,
        };
        add(&CRYPTO_TSC, t0);
        let total_discard = discard + extra_discard;
        self.incoming.drain(..total_discard.min(self.incoming.len()));
        if to_send > 0 {
            self.inner.write_all(&self.outgoing[..to_send])?;
        }
        if !plain.is_empty() {
            self.plaintext.extend_from_slice(&plain);
        }
        Ok(step)
    }
}

impl<S: Stream> Stream for TlsStream<S> {
    fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
        loop {
            if self.plain_pos < self.plaintext.len() {
                let n = (self.plaintext.len() - self.plain_pos).min(buf.len());
                buf[..n].copy_from_slice(&self.plaintext[self.plain_pos..self.plain_pos + n]);
                self.plain_pos += n;
                if self.plain_pos == self.plaintext.len() {
                    self.plaintext.clear();
                    self.plain_pos = 0;
                }
                return Ok(n);
            }
            match self.step(false)? {
                Step::Eof => return Ok(0),
                Step::NeedData => {
                    if self.eof {
                        return Ok(0); // peer closed without close_notify
                    }
                    self.fill()?;
                }
                Step::Continue | Step::HandshakeDone => {}
            }
        }
    }

    fn write_all(&mut self, buf: &[u8]) -> Result<()> {
        for chunk in buf.chunks(MAX_RECORD) {
            let n = loop {
                let UnbufferedStatus { state, .. } = self.conn.process_tls_records(&mut []);
                match state.map_err(|_| Error::Http("tls error"))? {
                    ConnectionState::WriteTraffic(mut w) => match w.encrypt(chunk, &mut self.outgoing) {
                        Ok(n) => break n,
                        Err(EncryptError::InsufficientSize(s)) => self.outgoing.resize(s.required_size, 0),
                        Err(_) => return Err(Error::Http("tls encrypt")),
                    },
                    ConnectionState::EncodeTlsData(mut e) => {
                        let n = e.encode(&mut self.outgoing).map_err(|_| Error::Http("tls encode"))?;
                        self.inner.write_all(&self.outgoing[..n])?;
                    }
                    ConnectionState::TransmitTlsData(t) => t.done(),
                    _ => return Err(Error::Closed),
                }
            };
            self.inner.write_all(&self.outgoing[..n])?;
        }
        Ok(())
    }
}

}

pub use stack::{Lease, Stack, TcpConn};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    Timeout,
    Dns,
    Connect,
    /// Peer closed the connection before the message was complete.
    Closed,
    Http(&'static str),
    Device(hal::Error),
}

pub type Result<T> = core::result::Result<T, Error>;

/// Blocking byte stream (plain TCP now, TLS on top later).
pub trait Stream {
    /// Blocks until at least one byte is available; returns 0 on orderly close.
    fn read(&mut self, buf: &mut [u8]) -> Result<usize>;
    fn write_all(&mut self, buf: &[u8]) -> Result<()>;
}

}
