#[cfg(all(archstaler_package = "loadcore", archstaler_target = "loadcore"))]
pub mod __archstaler_source {
//! The firmware-independent end of the boot loader. The firmware front ends (`boot/uefi`,
//! `boot/bios`) hand over a physical memory map, a framebuffer, the payload bundle and an arena of
//! memory they allocated for the loader. This crate unpacks the kernel and its modules into the
//! arena, builds the page tables (direct map, kernel, one identity-mapped trampoline page), fills
//! in a [`bootinfo::BootInfo`] and jumps to the kernel.
//!
//! Runs in 64-bit mode with every address it touches identity mapped.
mod map {
//! Physical memory map handling: firmware maps are unsorted, overlap, and are not page aligned.
use bootinfo::*;

const MAX: usize = 512;

/// How much a kind wins when ranges overlap (the safest reading of a bad firmware map).
fn strength(kind: u32) -> u8 {
    match kind {
        MEM_USABLE => 0,
        MEM_ACPI_RECLAIMABLE => 1,
        MEM_RESERVED => 2,
        MEM_ACPI_NVS => 3,
        MEM_LOADER => 4,
        _ => 5,
    }
}

pub struct Map {
    e: [MemEntry; MAX],
    n: usize,
    scratch: [MemEntry; MAX],
    points: [u64; 2 * MAX],
}

const ZERO: MemEntry = MemEntry { base: 0, len: 0, kind: 0, _pad: 0 };

impl Map {
    pub const fn new() -> Self {
        Map { e: [ZERO; MAX], n: 0, scratch: [ZERO; MAX], points: [0; 2 * MAX] }
    }

    pub fn len(&self) -> usize {
        self.n
    }

    pub fn entries(&self) -> &[MemEntry] {
        &self.e[..self.n]
    }

    /// Adds a raw range (call `normalize` after the last one). Contiguous neighbours of one kind merge,
    /// which keeps a sorted firmware map small.
    pub fn push(&mut self, base: u64, len: u64, kind: u32) {
        if len == 0 {
            return;
        }
        if let Some(last) = self.e[..self.n].last_mut() {
            if last.kind == kind && last.base + last.len == base {
                last.len += len;
                return;
            }
        }
        if self.n == MAX {
            panic!("memory map has too many entries");
        }
        self.e[self.n] = MemEntry { base, len, kind, _pad: 0 };
        self.n += 1;
    }

    /// Sorts, aligns (usable ranges shrink to whole pages, everything else grows), resolves overlaps
    /// (the strongest kind wins) and merges neighbours.
    pub fn normalize(&mut self) {
        let mut np = 0;
        for i in 0..self.n {
            let e = &mut self.e[i];
            let end = e.base.saturating_add(e.len);
            let (b, en) = if e.kind == MEM_USABLE { ((e.base + 4095) & !4095, end & !4095) } else { (e.base & !4095, end.saturating_add(4095) & !4095) };
            if en <= b {
                e.len = 0;
                continue;
            }
            e.base = b;
            e.len = en - b;
            self.points[np] = b;
            self.points[np + 1] = en;
            np += 2;
        }
        let pts = &mut self.points[..np];
        pts.sort_unstable();
        let mut out = 0;
        let mut k = 0;
        while k + 1 < np {
            let (lo, hi) = (pts[k], pts[k + 1]);
            k += 1;
            if lo == hi {
                continue;
            }
            let mut best: Option<u32> = None;
            for e in &self.e[..self.n] {
                if e.len != 0 && e.base <= lo && lo < e.base + e.len && best.map_or(true, |b| strength(e.kind) > strength(b)) {
                    best = Some(e.kind);
                }
            }
            let Some(kind) = best else { continue };
            if out > 0 && self.scratch[out - 1].kind == kind && self.scratch[out - 1].base + self.scratch[out - 1].len == lo {
                self.scratch[out - 1].len += hi - lo;
            } else {
                self.scratch[out] = MemEntry { base: lo, len: hi - lo, kind, _pad: 0 };
                out += 1;
            }
        }
        self.e[..out].copy_from_slice(&self.scratch[..out]);
        self.n = out;
    }

    /// Marks a range (usually carved out of usable memory) as `kind`.
    pub fn carve(&mut self, base: u64, len: u64, kind: u32) {
        self.push(base, len, kind);
        self.normalize();
    }

    /// The lowest usable range of `len` bytes at `align`, between `min` and `max` (exclusive).
    pub fn find_free(&self, len: u64, align: u64, min: u64, max: u64) -> Option<u64> {
        self.entries().iter().filter(|e| e.kind == MEM_USABLE).find_map(|e| {
            let start = (e.base.max(min) + align - 1) & !(align - 1);
            (start + len <= (e.base + e.len).min(max)).then_some(start)
        })
    }

    /// End of the highest range that is memory (not MMIO or holes).
    pub fn top(&self) -> u64 {
        self.entries().iter().filter(|e| matches!(e.kind, MEM_USABLE | MEM_ACPI_RECLAIMABLE | MEM_ACPI_NVS | MEM_LOADER)).map(|e| e.base + e.len).max().unwrap_or(0)
    }
}

#[cfg(test)]
mod tests {
    extern crate std;
    use super::*;
    use std::boxed::Box;
    use std::vec::Vec;

    fn kinds(m: &Map) -> Vec<(u64, u64, u32)> {
        m.entries().iter().map(|e| (e.base, e.len, e.kind)).collect()
    }

    #[test]
    fn sorts_and_merges() {
        let mut m = Box::new(Map::new());
        m.push(0x20_0000, 0x10_0000, MEM_USABLE);
        m.push(0x10_0000, 0x10_0000, MEM_USABLE);
        m.normalize();
        assert_eq!(kinds(&m), [(0x10_0000, 0x20_0000, MEM_USABLE)]);
    }

    #[test]
    fn reserved_wins_over_usable() {
        let mut m = Box::new(Map::new());
        m.push(0x10_0000, 0x40_0000, MEM_USABLE);
        m.push(0x20_0000, 0x1000, MEM_RESERVED);
        m.normalize();
        assert_eq!(
            kinds(&m),
            [(0x10_0000, 0x10_0000, MEM_USABLE), (0x20_0000, 0x1000, MEM_RESERVED), (0x20_1000, 0x2f_f000, MEM_USABLE)]
        );
    }

    #[test]
    fn usable_shrinks_and_reserved_grows_to_pages() {
        let mut m = Box::new(Map::new());
        m.push(0x1800, 0x3000, MEM_USABLE); // 0x1800..0x4800 -> 0x2000..0x4000
        m.push(0x10_0800, 0x100, MEM_RESERVED); // -> the whole page
        m.normalize();
        assert_eq!(kinds(&m), [(0x2000, 0x2000, MEM_USABLE), (0x10_0000, 0x1000, MEM_RESERVED)]);
    }

    #[test]
    fn carve_and_find_free() {
        let mut m = Box::new(Map::new());
        m.push(0x10_0000, 0x100_0000, MEM_USABLE);
        m.normalize();
        assert_eq!(m.find_free(0x1000, 0x1000, 0x10_0000, u64::MAX), Some(0x10_0000));
        m.carve(0x10_0000, 0x20_0000, MEM_LOADER);
        assert_eq!(m.find_free(0x1000, 0x1000, 0x10_0000, u64::MAX), Some(0x30_0000));
        assert_eq!(m.find_free(0x1000, 0x20_0000, 0x10_0000, u64::MAX), Some(0x40_0000));
        assert_eq!(m.find_free(0x1000, 0x1000, 0x10_0000, 0x30_0000), None);
        assert_eq!(m.top(), 0x110_0000);
    }
}

}
mod paging {
//! The kernel's initial page tables.
use crate::__archstaler_source::{up, Arena, HUGE, PAGE};
use bootinfo::*;

const P: u64 = 1;
const W: u64 = 2;
const PS: u64 = 1 << 7;
const ADDR: u64 = 0x000f_ffff_ffff_f000;
/// The direct map covers at most this much (one PML4 slot).
const HHDM_MAX: u64 = 512 << 30;

unsafe fn new_table(arena: &mut Arena) -> *mut u64 {
    arena.take(PAGE, PAGE) as *mut u64
}

/// Entry `idx` of `table`, creating the next level when it is empty.
unsafe fn next(arena: &mut Arena, table: *mut u64, idx: u64) -> *mut u64 {
    let e = table.add(idx as usize);
    if *e & P == 0 {
        *e = new_table(arena) as u64 | P | W;
    }
    (*e & ADDR) as *mut u64
}

unsafe fn map_2m(arena: &mut Arena, pml4: *mut u64, virt: u64, phys: u64) {
    let pdpt = next(arena, pml4, (virt >> 39) & 511);
    let pd = next(arena, pdpt, (virt >> 30) & 511);
    *pd.add(((virt >> 21) & 511) as usize) = phys | P | W | PS;
}

unsafe fn map_4k(arena: &mut Arena, pml4: *mut u64, virt: u64, phys: u64) {
    let pdpt = next(arena, pml4, (virt >> 39) & 511);
    let pd = next(arena, pdpt, (virt >> 30) & 511);
    let pt = next(arena, pd, (virt >> 21) & 511);
    *pt.add(((virt >> 12) & 511) as usize) = phys | P | W;
}

/// Returns the physical address of the PML4: the direct map (the first 4 GiB, every memory range,
/// the framebuffer), the kernel at `KERNEL_BASE`, and the trampoline page identity mapped.
pub unsafe fn build(arena: &mut Arena, map: &crate::__archstaler_source::Map, kernel_phys: u64, kernel_mem: u64, tramp: u64, fb: &Framebuffer) -> u64 {
    let pml4 = new_table(arena);
    let hhdm = |arena: &mut Arena, base: u64, end: u64| {
        let mut a = base & !(HUGE - 1);
        while a < end.min(HHDM_MAX) {
            map_2m(arena, pml4, HHDM_BASE + a, a);
            a += HUGE;
        }
    };
    hhdm(arena, 0, 4 << 30);
    for e in map.entries() {
        if e.kind != MEM_BAD {
            hhdm(arena, e.base, e.base + e.len);
        }
    }
    if fb.addr != 0 {
        hhdm(arena, fb.addr, fb.addr + fb.pitch as u64 * fb.height as u64);
    }
    for i in 0..up(kernel_mem, HUGE) / HUGE {
        map_2m(arena, pml4, KERNEL_BASE + i * HUGE, kernel_phys + i * HUGE);
    }
    map_4k(arena, pml4, tramp, tramp);
    pml4 as u64
}

}

pub use map::Map;

use bootinfo::*;
use core::arch::{asm, global_asm};
use miniz_oxide::inflate::core::{decompress, inflate_flags::TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF, DecompressorOxide};
use miniz_oxide::inflate::TINFLStatus;

const PAGE: u64 = 4096;
const HUGE: u64 = 2 << 20;

/// Writes to COM1 (no setup: QEMU and most firmware leave it usable; a machine without it ignores the writes).
pub fn log(msg: &str) {
    for b in msg.bytes() {
        unsafe { asm!("out dx, al", in("dx") 0x3f8u16, in("al") b, options(nomem, nostack)) };
    }
}

pub fn log_hex(mut v: u64) {
    let mut buf = [0u8; 16];
    for i in (0..16).rev() {
        buf[i] = b"0123456789abcdef"[(v & 15) as usize];
        v >>= 4;
    }
    log("0x");
    log(core::str::from_utf8(&buf).unwrap());
}

fn le32(b: &[u8], at: usize) -> u32 {
    u32::from_le_bytes(b[at..at + 4].try_into().unwrap())
}
fn le64(b: &[u8], at: usize) -> u64 {
    u64::from_le_bytes(b[at..at + 8].try_into().unwrap())
}
fn up(v: u64, to: u64) -> u64 {
    (v + to - 1) & !(to - 1)
}

/// What the payload asks for: the kernel, then modules.
struct Payload<'a> {
    bytes: &'a [u8],
    count: usize,
    kernel_entry: u64,
    kernel_mem: u64,
}

impl<'a> Payload<'a> {
    fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < PAYLOAD_HEADER || le32(bytes, 0) != PAYLOAD_MAGIC {
            return None;
        }
        let count = le32(bytes, 4) as usize;
        let kernel_entry = le64(bytes, 8);
        let kernel_mem = le32(bytes, 16) as u64;
        (bytes.len() >= PAYLOAD_HEADER + 16 + count * PAYLOAD_ENTRY).then_some(Payload { bytes, count, kernel_entry, kernel_mem })
    }
    /// (name, stored data, raw length, deflated)
    fn entry(&self, i: usize) -> (&'a [u8], &'a [u8], usize, bool) {
        let at = PAYLOAD_HEADER + 16 + i * PAYLOAD_ENTRY;
        let name = &self.bytes[at..at + 16];
        let (off, stored, raw, flags) = (le32(self.bytes, at + 16) as usize, le32(self.bytes, at + 20) as usize, le32(self.bytes, at + 24) as usize, le32(self.bytes, at + 28));
        (name, &self.bytes[off..off + stored], raw, flags & FLAG_DEFLATE != 0)
    }
}

/// The number of bytes of arena `boot` needs for this payload and a machine whose memory ends at `max_phys`.
pub fn arena_size(payload: &[u8], max_phys: u64) -> Option<u64> {
    let p = Payload::parse(payload)?;
    let mut n = up(p.kernel_mem, HUGE) + HUGE; // the kernel is 2 MiB aligned inside the arena
    for i in 0..p.count {
        n += up(p.entry(i).2 as u64, PAGE) + PAGE;
    }
    n += STACK_SIZE + 64 * PAGE; // stack, boot info, memory map, trampoline
    let gib = up(max_phys.max(4 << 30), 1 << 30) >> 30;
    n += (gib + 16) * PAGE; // direct map: one page directory per GiB, plus the fixed tables
    Some(up(n, PAGE))
}

struct Arena {
    next: u64,
    end: u64,
}

impl Arena {
    fn take(&mut self, len: u64, align: u64) -> u64 {
        let at = up(self.next, align);
        if at + len > self.end {
            panic!("loader arena exhausted");
        }
        self.next = at + len;
        unsafe { core::ptr::write_bytes(at as *mut u8, 0, len as usize) };
        at
    }
}

pub struct Boot<'a> {
    pub firmware: u32,
    pub fb: Framebuffer,
    pub payload: &'a [u8],
    /// Physical range, 4 KiB aligned, at least `arena_size` bytes, already allocated from the firmware.
    pub arena: (u64, u64),
}

fn unpack(stored: &[u8], raw: usize, deflated: bool, dest: u64) {
    let out = unsafe { core::slice::from_raw_parts_mut(dest as *mut u8, raw) };
    if !deflated {
        out.copy_from_slice(&stored[..raw]);
        return;
    }
    let mut d = DecompressorOxide::new();
    let (status, _, n) = decompress(&mut d, stored, out, 0, TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF);
    if status != TINFLStatus::Done || n != raw {
        panic!("payload entry is corrupt");
    }
}

global_asm!(
    r#"
    .text
    .balign 16
    .global loadcore_tramp_start
    .global loadcore_tramp_end
    .global loadcore_tramp_gdtr
loadcore_tramp_start:
    cli
    lgdt [rip + loadcore_tramp_gdtr]
    mov cr3, rax
    mov rsp, rcx
    lea r9, [rip + 2f]
    push 0x08
    push r9
    retfq
2:
    mov ax, 0x10
    mov ds, ax
    mov es, ax
    mov ss, ax
    xor eax, eax
    mov fs, ax
    mov gs, ax
    mov rdi, rdx
    xor ebp, ebp
    push 0
    jmp r8
    .balign 16
loadcore_tramp_gdtr:
    .quad 0
    .quad 0
loadcore_tramp_end:
    "#
);

extern "C" {
    static loadcore_tramp_start: u8;
    static loadcore_tramp_end: u8;
    static loadcore_tramp_gdtr: u8;
}

/// Unpacks the payload and enters the kernel. `map` is the final memory map (the firmware must not
/// allocate or free after it was taken).
///
/// # Safety
/// The caller is the boot loader at its last step: everything in `map` and the arena is identity mapped and unused.
pub unsafe fn boot(map: &mut Map, b: Boot) -> ! {
    let payload = Payload::parse(b.payload).expect("payload bundle is missing or damaged");
    if payload.kernel_mem == 0 || payload.kernel_mem > KERNEL_MAX {
        panic!("kernel image size is out of range");
    }
    map.carve(b.arena.0, b.arena.1, MEM_LOADER);
    let mut arena = Arena { next: b.arena.0, end: b.arena.0 + b.arena.1 };

    // The kernel.
    let kernel_phys = arena.take(up(payload.kernel_mem, HUGE), HUGE);
    let mut modules = [Module { name: [0; 16], addr: 0, len: 0 }; 16];
    let mut nmod = 0;
    let mut have_kernel = false;
    for i in 0..payload.count {
        let (name, stored, raw, deflated) = payload.entry(i);
        let n = name.iter().position(|&c| c == 0).unwrap_or(16);
        if &name[..n] == b"kernel" {
            if raw as u64 > payload.kernel_mem {
                panic!("kernel image is larger than its memory size");
            }
            unpack(stored, raw, deflated, kernel_phys);
            have_kernel = true;
        } else {
            if nmod == modules.len() {
                panic!("too many payload modules");
            }
            let dest = arena.take(raw as u64, PAGE);
            unpack(stored, raw, deflated, dest);
            modules[nmod] = Module { name: name.try_into().unwrap(), addr: HHDM_BASE + dest, len: raw as u64 };
            nmod += 1;
        }
    }
    if !have_kernel {
        panic!("payload has no kernel");
    }
    log("loader: payload unpacked\n");

    let stack = arena.take(STACK_SIZE, PAGE);
    let tramp = arena.take(PAGE, PAGE);

    // Boot info: the structure, the modules, the memory map.
    let info_len = up(core::mem::size_of::<BootInfo>() as u64 + (nmod * core::mem::size_of::<Module>()) as u64 + (map.len() * core::mem::size_of::<MemEntry>()) as u64 + 64, PAGE);
    let info_phys = arena.take(info_len, PAGE);

    let cr3 = paging::build(&mut arena, map, kernel_phys, payload.kernel_mem, tramp, &b.fb);

    // Modules and memory map, after the page tables took their pages out of the map's accounting.
    let mods_phys = info_phys + core::mem::size_of::<BootInfo>() as u64;
    let mem_phys = mods_phys + (nmod * core::mem::size_of::<Module>()) as u64;
    core::ptr::copy_nonoverlapping(modules.as_ptr(), mods_phys as *mut Module, nmod);
    core::ptr::copy_nonoverlapping(map.entries().as_ptr(), mem_phys as *mut MemEntry, map.len());
    let info = info_phys as *mut BootInfo;
    info.write(BootInfo {
        magic: MAGIC,
        hhdm: HHDM_BASE,
        firmware: b.firmware,
        _pad: 0,
        fb: b.fb,
        mem: (HHDM_BASE + mem_phys) as *const MemEntry,
        mem_len: map.len() as u64,
        modules: (HHDM_BASE + mods_phys) as *const Module,
        modules_len: nmod as u64,
    });

    // Trampoline page: code, then a GDT (null, 64-bit code, data) the code loads.
    let start = &loadcore_tramp_start as *const u8;
    let code_len = &loadcore_tramp_end as *const u8 as usize - start as usize;
    core::ptr::copy_nonoverlapping(start, tramp as *mut u8, code_len);
    let gdtr_at = tramp + (&loadcore_tramp_gdtr as *const u8 as usize - start as usize) as u64;
    let gdt_at = tramp + PAGE - 64;
    let gdt = gdt_at as *mut u64;
    gdt.write(0);
    gdt.add(1).write(0x00af_9a00_0000_ffff);
    gdt.add(2).write(0x00cf_9200_0000_ffff);
    (gdtr_at as *mut u16).write(3 * 8 - 1);
    ((gdtr_at + 2) as *mut u64).write(gdt_at);

    log("loader: entering kernel\n");
    asm!(
        "jmp {t}",
        t = in(reg) tramp,
        in("rax") cr3,
        in("rdx") HHDM_BASE + info_phys,
        in("rcx") HHDM_BASE + stack + STACK_SIZE,
        in("r8") payload.kernel_entry,
        options(noreturn)
    )
}

}
